package com.aether.launcher.settings

import android.content.Context
import android.content.Intent
import android.graphics.Color
import android.graphics.Typeface
import android.provider.Settings
import android.view.Gravity
import android.view.View
import android.widget.*
import com.aether.launcher.AetherRuntime
import kotlin.math.roundToInt

/** Post-setup settings surface. Categories expose the same configuration used by the setup wizard. */
class AetherSettingsView(context: Context) : ScrollView(context) {
    private val store = AetherSettingsStore(context)
    private var settings = store.load()
    private val root = LinearLayout(context).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(20), dp(26), dp(20), dp(32)) }
    private var category: String? = null

    init { setFillViewport(true); setBackgroundColor(0xFF080A0E.toInt()); addView(root); render() }

    private fun render() {
        root.removeAllViews()
        if (category == null) home() else detail(category!!)
    }

    private fun header(title: String, subtitle: String) {
        val row = LinearLayout(context).apply { gravity = Gravity.CENTER_VERTICAL; setPadding(0,0,0,dp(16)) }
        if (category != null) row.addView(Button(context).apply { text = "‹"; textSize=27f; setTextColor(Color.WHITE); setOnClickListener{category=null;render()} }, LinearLayout.LayoutParams(dp(56),dp(52)))
        val box=LinearLayout(context).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(4),0,0,0)}
        box.addView(text(title,30f,Color.WHITE,true)); box.addView(text(subtitle,14f,0xAFFFFFFF.toInt(),false))
        row.addView(box,LinearLayout.LayoutParams(0,-2,1f)); root.addView(row)
    }

    private fun home() {
        header("Aether Settings", "Everything you chose during setup can be changed here.")
        root.addView(summaryCard())
        root.addView(sectionLabel("Personalize"))
        categoryCard("Home", "Home mode, app placement and home behavior", "home")
        categoryCard("Grid & Icons", "Rows, columns, size, spacing, labels and folders", "grid")
        categoryCard("Dock", "Dock apps, grouping and smart folders", "dock")
        categoryCard("Appearance & Glass", "Theme, liquid-glass material and visual depth", "appearance")
        categoryCard("Motion", "Spring, bounce, speed and gesture feel", "motion")
        root.addView(sectionLabel("Aether Features"))
        categoryCard("Dynamic Island", "Cutout adaptation, activities and behavior", "island")
        categoryCard("Quick Space", "Edge handle, tools and swipe behavior", "quick")
        categoryCard("Control Center", "Tiles, gesture corner and panel layout", "control")
        categoryCard("Floating Windows", "Window size, resize, snap and limits", "windows")
        categoryCard("Split Screen", "Ratios, divider and remembered layouts", "split")
        categoryCard("Security & App Lock", "Protected apps, relocking and authentication", "security")
        root.addView(sectionLabel("System Setup"))
        categoryCard("Permissions & Access", "Open Android controls for Aether capabilities", "permissions")
        categoryCard("Reset Setup", "Return Aether to first-run defaults", "reset")
    }

    private fun detail(key:String) {
        when(key){
            "home" -> homeDetail(); "grid" -> gridDetail(); "dock" -> dockDetail(); "appearance" -> appearanceDetail(); "motion" -> motionDetail(); "island" -> islandDetail(); "quick" -> quickDetail(); "control" -> controlDetail(); "windows" -> windowsDetail(); "split" -> splitDetail(); "security" -> securityDetail(); "permissions" -> permissionsDetail(); "reset" -> resetDetail()
        }
    }

    private fun homeDetail(){ header("Home", "Choose how Aether presents your apps."); enumChoice("Home mode",HomeMode.values().toList(),settings.homeMode){settings=settings.copy(homeMode=it);save()}; root.addView(preview("Home layout preview",180)) }
    private fun gridDetail(){ header("Grid & Icons", "Control density, labels, folders and spacing."); slider("Apps per row",3,7,settings.grid.columns){editGrid{copy(columns=it)}};slider("Rows",4,9,settings.grid.rows){editGrid{copy(rows=it)}};slider("Icon size",40,72,settings.grid.iconSize){editGrid{copy(iconSize=it)}};slider("Horizontal spacing",4,28,settings.grid.horizontalSpacing){editGrid{copy(horizontalSpacing=it)}};slider("Vertical spacing",6,32,settings.grid.verticalSpacing){editGrid{copy(verticalSpacing=it)}};slider("Horizontal padding",8,40,settings.grid.horizontalPadding){editGrid{copy(horizontalPadding=it)}};slider("Vertical padding",8,48,settings.grid.verticalPadding){editGrid{copy(verticalPadding=it)}};toggle("Show app labels",settings.grid.showLabels){editGrid{copy(showLabels=it)}};slider("Label size",9,16,settings.grid.labelSize){editGrid{copy(labelSize=it)}};enumChoice("Folder style",FolderStyle.values().toList(),settings.grid.folderStyle){editGrid{copy(folderStyle=it)}};slider("Folder corner radius",8,40,settings.grid.folderRadius){editGrid{copy(folderRadius=it)}}}
    private fun dockDetail(){ header("Dock", "Configure the bottom bar and smart grouping.");toggle("Use dock",settings.dock.enabled){editDock{copy(enabled=it)}};slider("Dock apps",3,8,settings.dock.appCount){editDock{copy(appCount=it)}};slider("Dock height",56,110,settings.dock.height){editDock{copy(height=it)}};slider("Dock corner radius",12,44,settings.dock.radius){editDock{copy(radius=it)}};slider("Bottom padding",4,40,settings.dock.bottomPadding){editDock{copy(bottomPadding=it)}};toggle("Auto-group similar apps",settings.dock.autoGroup){editDock{copy(autoGroup=it)}};toggle("Group by company",settings.dock.groupByCompany){editDock{copy(groupByCompany=it)}};toggle("Group by category",settings.dock.groupByCategory){editDock{copy(groupByCategory=it)}};toggle("Smart groups",settings.dock.smartGroups){editDock{copy(smartGroups=it)}}}
    private fun appearanceDetail(){ header("Appearance & Glass", "Tune Aether's material, theme and visual character.");enumChoice("Theme",AppearanceTheme.values().toList(),settings.appearance.theme){settings=settings.copy(appearance=settings.appearance.copy(theme=it));save()};slider("Corner radius",8,42,settings.glass.cornerRadius){editGlass{copy(cornerRadius=it)}};slider("Glass opacity",45,100,settings.glass.opacity){editGlass{copy(opacity=it)}};slider("Blur",0,50,settings.glass.blur){editGlass{copy(blur=it)}};slider("Saturation",80,135,settings.glass.saturation){editGlass{copy(saturation=it)}};slider("Refraction",0,40,settings.glass.refraction){editGlass{copy(refraction=it)}};slider("Highlights",0,100,settings.glass.highlight){editGlass{copy(highlight=it)}};slider("Depth",0,20,settings.glass.depth){editGlass{copy(depth=it)}};slider("Border",0,100,settings.glass.border){editGlass{copy(border=it)}};slider("Wallpaper dim",0,40,settings.appearance.wallpaperDim){settings=settings.copy(appearance=settings.appearance.copy(wallpaperDim=it));save()};toggle("Show time",settings.appearance.showTime){settings=settings.copy(appearance=settings.appearance.copy(showTime=it));save()};toggle("Show AETHER label",settings.appearance.showAetherLabel){settings=settings.copy(appearance=settings.appearance.copy(showAetherLabel=it));save()};enumChoice("Motion preset",MotionPreset.values().toList(),settings.motion.preset){editMotion{copy(preset=it)}}}
    private fun motionDetail(){ header("Motion", "Make interactions soft, balanced, fluid or elastic.");enumChoice("Preset",MotionPreset.values().toList(),settings.motion.preset){editMotion{copy(preset=it)}};slider("Speed",50,160,settings.motion.speed){editMotion{copy(speed=it)}};slider("Spring strength",150,800,settings.motion.springStrength){editMotion{copy(springStrength=it)}};slider("Damping",10,80,settings.motion.damping){editMotion{copy(damping=it)}};slider("Bounce",0,40,settings.motion.bounce){editMotion{copy(bounce=it)}};slider("Gesture sensitivity",10,100,settings.motion.gestureSensitivity){editMotion{copy(gestureSensitivity=it)}};root.addView(preview("Motion response preview",170))}
    private fun islandDetail(){ header("Dynamic Island", "The top activity surface can adapt to your camera cutout and live events.");toggle("Enable Dynamic Island",settings.island.enabled){editIsland{copy(enabled=it)}};toggle("Adapt around camera cutout",settings.island.cutoutAware){editIsland{copy(cutoutAware=it)}};slider("Width",72,180,settings.island.width){editIsland{copy(width=it)}};slider("Height",24,70,settings.island.height){editIsland{copy(height=it)}};slider("Corner radius",8,35,settings.island.radius){editIsland{copy(radius=it)}};slider("Top offset",0,40,settings.island.topOffset){editIsland{copy(topOffset=it)}};toggle("Blur around cutout",settings.island.blurSurroundingCutout){editIsland{copy(blurSurroundingCutout=it)}};toggle("Notifications",settings.island.showNotifications){editIsland{copy(showNotifications=it)}};toggle("Media",settings.island.showMedia){editIsland{copy(showMedia=it)}};toggle("Calls",settings.island.showCalls){editIsland{copy(showCalls=it)}};toggle("Timers / alarms",settings.island.showTimers){editIsland{copy(showTimers=it)}};toggle("Recording",settings.island.showRecording){editIsland{copy(showRecording=it)}};toggle("Navigation",settings.island.showNavigation){editIsland{copy(showNavigation=it)}}}
    private fun quickDetail(){ header("Quick Space", "Your fast lane lives behind the edge handle.");toggle("Enable Quick Space",settings.quickSpace.enabled){editQuick{copy(enabled=it)}};enumChoice("Edge",QuickEdge.values().toList(),settings.quickSpace.edge){editQuick{copy(edge=it)}};slider("Handle thickness",3,12,settings.quickSpace.handleThickness){editQuick{copy(handleThickness=it)}};slider("Handle length",24,90,settings.quickSpace.handleLength){editQuick{copy(handleLength=it)}};slider("Trigger distance",40,180,settings.quickSpace.triggerDistance){editQuick{copy(triggerDistance=it)}};slider("Sensitivity",10,100,settings.quickSpace.sensitivity){editQuick{copy(sensitivity=it)}};slider("Panel width",70,96,settings.quickSpace.panelWidth){editQuick{copy(panelWidth=it)}};slider("Panel height",28,70,settings.quickSpace.panelHeight){editQuick{copy(panelHeight=it)}};toggle("Notes",settings.quickSpace.notes){editQuick{copy(notes=it)}};toggle("Voice recorder",settings.quickSpace.recorder){editQuick{copy(recorder=it)}};toggle("Calculator",settings.quickSpace.calculator){editQuick{copy(calculator=it)}};toggle("Screenshot",settings.quickSpace.screenshot){editQuick{copy(screenshot=it)}};toggle("Clipboard",settings.quickSpace.clipboard){editQuick{copy(clipboard=it)}};toggle("Recent apps",settings.quickSpace.recentApps){editQuick{copy(recentApps=it)}};toggle("Shortcuts",settings.quickSpace.shortcuts){editQuick{copy(shortcuts=it)}}}
    private fun controlDetail(){ header("Control Center", "Tune the system panel and its tiles.");toggle("Enable Control Center",settings.controlCenter.enabled){editControl{copy(enabled=it)}};enumChoice("Gesture corner",ControlEdge.values().toList(),settings.controlCenter.edge){editControl{copy(edge=it)}};slider("Tile columns",1,4,settings.controlCenter.columns){editControl{copy(columns=it)}};slider("Tile radius",10,40,settings.controlCenter.tileRadius){editControl{copy(tileRadius=it)}};slider("Panel radius",12,44,settings.controlCenter.panelRadius){editControl{copy(panelRadius=it)}};toggle("Brightness",settings.controlCenter.showBrightness){editControl{copy(showBrightness=it)}};toggle("Volume",settings.controlCenter.showVolume){editControl{copy(showVolume=it)}};toggle("Wi-Fi",settings.controlCenter.showWifi){editControl{copy(showWifi=it)}};toggle("Bluetooth",settings.controlCenter.showBluetooth){editControl{copy(showBluetooth=it)}};toggle("Airplane mode",settings.controlCenter.showAirplane){editControl{copy(showAirplane=it)}};toggle("Rotation",settings.controlCenter.showRotation){editControl{copy(showRotation=it)}};toggle("Flashlight",settings.controlCenter.showFlashlight){editControl{copy(showFlashlight=it)}};toggle("Do Not Disturb",settings.controlCenter.showDnd){editControl{copy(showDnd=it)}}}
    private fun windowsDetail(){ header("Floating Windows", "Configure Aether's floating interaction layer and split-screen defaults.");toggle("Enable floating windows",settings.floatingWindows.enabled){editFloat{copy(enabled=it)}};slider("Default width",50,95,settings.floatingWindows.defaultWidth){editFloat{copy(defaultWidth=it)}};slider("Default height",40,90,settings.floatingWindows.defaultHeight){editFloat{copy(defaultHeight=it)}};slider("Window radius",10,42,settings.floatingWindows.radius){editFloat{copy(radius=it)}};slider("Window opacity",55,100,settings.floatingWindows.transparency){editFloat{copy(transparency=it)}};slider("Shadow",0,100,settings.floatingWindows.shadow){editFloat{copy(shadow=it)}};slider("Maximum windows",1,6,settings.floatingWindows.maxWindows){editFloat{copy(maxWindows=it)}};toggle("Resize from edges",settings.floatingWindows.edgeResize){editFloat{copy(edgeResize=it)}};toggle("Resize from corners",settings.floatingWindows.cornerResize){editFloat{copy(cornerResize=it)}};toggle("Snap windows",settings.floatingWindows.snapWindows){editFloat{copy(snapWindows=it)}};toggle("Remember positions",settings.floatingWindows.rememberPositions){editFloat{copy(rememberPositions=it)}}}
    private fun splitDetail(){ header("Split Screen", "Configure ratios and the divider feel.");toggle("Enable split screen",settings.splitScreen.enabled){editSplit{copy(enabled=it)}};slider("Default ratio",30,70,settings.splitScreen.defaultRatio){editSplit{copy(defaultRatio=it)}};toggle("Allow custom ratios",settings.splitScreen.allowCustomRatio){editSplit{copy(allowCustomRatio=it)}};toggle("Remember layouts",settings.splitScreen.rememberLayouts){editSplit{copy(rememberLayouts=it)}};toggle("Snap divider",settings.splitScreen.snapToEdges){editSplit{copy(snapToEdges=it)}};slider("Divider thickness",2,12,settings.splitScreen.dividerThickness){editSplit{copy(dividerThickness=it)}};root.addView(preview("Split  ${settings.splitScreen.defaultRatio}/${100-settings.splitScreen.defaultRatio}",150))}
    private fun securityDetail(){ header("Security & App Lock", "Choose which apps are protected and how Aether relocks them.");toggle("App Lock",settings.security.appLockEnabled){editSecurity{copy(appLockEnabled=it)}};toggle("Relock when leaving app",settings.security.relockOnLeave){editSecurity{copy(relockOnLeave=it)}};toggle("Relock on screen off",settings.security.relockOnScreenOff){editSecurity{copy(relockOnScreenOff=it)}};slider("Relock timeout (seconds)",0,300,settings.security.relockTimeoutSeconds){editSecurity{copy(relockTimeoutSeconds=it)}};toggle("Use biometrics",settings.security.useBiometrics){editSecurity{copy(useBiometrics=it)}};toggle("Use device credential",settings.security.useDeviceCredential){editSecurity{copy(useDeviceCredential=it)}};toggle("Hide locked apps",settings.security.hideLockedApps){editSecurity{copy(hideLockedApps=it)}};root.addView(sectionLabel("Protected apps"));protectedApps()}
    private fun permissionsDetail(){ header("Permissions & Access", "Aether only gets capabilities you explicitly enable in Android.");action("Set as default launcher","Open Android's Home app chooser"){context.startActivity(Intent(Settings.ACTION_HOME_SETTINGS))};action("Display over other apps","Required for Quick Space and the floating Island"){context.startActivity(Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION).setData(android.net.Uri.parse("package:"+context.packageName)))};action("Notification access","Let Aether read notifications for Dynamic Island"){context.startActivity(Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"))};action("Accessibility","Enable foreground app sensing and app-lock interception"){context.startActivity(Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS))};action("Shizuku","Open Shizuku settings if installed"){context.startActivity(Intent(Intent.ACTION_VIEW).setData(android.net.Uri.parse("https://shizuku.rikka.app/")))} }
    private fun resetDetail(){ header("Reset Setup", "Restore factory setup choices. Your protected app policy is left untouched until you change it.");action("Reset all visual and feature settings","Returns AetherSettings to defaults and sends you through setup again."){ AlertDialog.Builder(context).setTitle("Reset Aether setup?").setMessage("This resets layout, appearance, island, Quick Space, Control Center and window preferences.").setNegativeButton("Cancel",null).setPositiveButton("Reset"){_,_->store.resetSetup();settings=store.load();Toast.makeText(context,"Setup reset",Toast.LENGTH_SHORT).show();category=null;render()} .show() } }

    private fun protectedApps(){ val apps=AetherRuntime.registry.launcher.apps().sortedBy{it.label.lowercase()}; val current=AetherRuntime.security.protectedApps(); apps.forEach{app->val row=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};row.addView(text(app.label,14f,Color.WHITE,false),LinearLayout.LayoutParams(0,dp(52),1f));val box=CheckBox(context).apply{isChecked=app.packageName in current;setOnCheckedChangeListener{_,checked->if(checked)AetherRuntime.security.protect(app.packageName)else AetherRuntime.security.unprotect(app.packageName)}};row.addView(box,LinearLayout.LayoutParams(dp(58),dp(52)));root.addView(row)} }

    private fun summaryCard():View { val s=TextView(context);s.text="${settings.homeMode.name.replace('_',' ')}  •  ${settings.grid.columns}×${settings.grid.rows}  •  Island ${if(settings.island.enabled) "On" else "Off"}  •  Quick Space ${if(settings.quickSpace.enabled) "On" else "Off"}\nGlass ${settings.glass.opacity}%  •  Dock ${settings.dock.appCount} apps  •  Max windows ${settings.floatingWindows.maxWindows}";s.setTextColor(Color.WHITE);s.textSize=14f;s.setPadding(dp(18),dp(18),dp(18),dp(18));s.setBackgroundColor(0x171E2630);return s}
    private fun categoryCard(title:String,desc:String,key:String){val v=Button(context).apply{text="$title\n$desc";gravity=Gravity.START or Gravity.CENTER_VERTICAL;setTextColor(Color.WHITE);textSize=14f;setPadding(dp(18),0,dp(18),0);setOnClickListener{category=key;render()}};root.addView(v,LinearLayout.LayoutParams(-1,dp(72)).apply{bottomMargin=dp(8)})}
    private fun sectionLabel(t:String){root.addView(text(t,19f,Color.WHITE,true),LinearLayout.LayoutParams(-1,dp(50)))}
    private fun action(title:String,desc:String,onClick:()->Unit){val b=Button(context).apply{text="$title\n$desc";gravity=Gravity.START or Gravity.CENTER_VERTICAL;setTextColor(Color.WHITE);textSize=14f;setOnClickListener{runCatching{onClick()}.onFailure{Toast.makeText(context,"Unavailable on this device",Toast.LENGTH_SHORT).show()}}};root.addView(b,LinearLayout.LayoutParams(-1,dp(76)).apply{bottomMargin=dp(8)})}
    private fun preview(label:String,h:Int)=object:View(context){val p=android.graphics.Paint(1);override fun onDraw(c:android.graphics.Canvas){p.color=0x18212A33;c.drawRoundRect(0f,0f,width.toFloat(),h.toFloat(),28f,28f,p);p.color=0x50FFFFFF;c.drawRoundRect(12f,12f,width-12f,h-12f,22f,22f,p);p.color=Color.WHITE;p.textAlign=android.graphics.Paint.Align.CENTER;p.textSize=13f;c.drawText(label,width/2f,34f,p)}}.also{it.layoutParams=LinearLayout.LayoutParams(-1,dp(h)).apply{topMargin=dp(8);bottomMargin=dp(12)}}
    private fun slider(label:String,min:Int,max:Int,value:Int,action:(Int)->Unit):View{val box=LinearLayout(context).apply{orientation=LinearLayout.VERTICAL;setPadding(0,dp(6),0,dp(4))};val row=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};val t=text(label,14f,Color.WHITE,false);val v=text(value.toString(),12f,0xB5FFFFFF.toInt(),false);v.gravity=Gravity.END;row.addView(t,LinearLayout.LayoutParams(0,dp(28),1f));row.addView(v,LinearLayout.LayoutParams(dp(56),dp(28)));val sb=SeekBar(context).apply{max=max-min;progress=(value-min).coerceIn(0,max-min);setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,p:Int,u:Boolean){v.text=(p+min).toString();if(u)action(p+min)};override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?) {}})};box.addView(row);box.addView(sb);root.addView(box);return box}
    private fun toggle(label:String,value:Boolean,action:(Boolean)->Unit):View{val row=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};row.addView(text(label,14f,Color.WHITE,false),LinearLayout.LayoutParams(0,dp(54),1f));row.addView(Switch(context).apply{isChecked=value;setOnCheckedChangeListener{_,c->action(c)}},LinearLayout.LayoutParams(dp(62),dp(52)));root.addView(row);return row}
    private fun <E:Enum<E>> enumChoice(label:String,values:List<E>,selected:E,action:(E)->Unit){val row=LinearLayout(context).apply{gravity=Gravity.CENTER_VERTICAL};row.addView(text(label,14f,Color.WHITE,false),LinearLayout.LayoutParams(0,dp(54),1f));val sp=Spinner(context);sp.adapter=ArrayAdapter(context,android.R.layout.simple_spinner_dropdown_item,values.map{it.name.replace('_',' ').lowercase().replaceFirstChar{ch->ch.uppercase()}});sp.setSelection(values.indexOf(selected));sp.onItemSelectedListener=object:AdapterView.OnItemSelectedListener{override fun onItemSelected(p:AdapterView<*>?,v:View?,pos:Int,id:Long){action(values[pos])};override fun onNothingSelected(p:AdapterView<*>?) {}};row.addView(sp,LinearLayout.LayoutParams(dp(180),dp(54)));root.addView(row)}
    private fun save(){store.save(settings)}
    private fun editGrid(f:GridSettings.()->GridSettings){settings=settings.copy(grid=settings.grid.f());save()};private fun editDock(f:DockSettings.()->DockSettings){settings=settings.copy(dock=settings.dock.f());save()};private fun editGlass(f:GlassSettings.()->GlassSettings){settings=settings.copy(glass=settings.glass.f());save()};private fun editMotion(f:MotionSettings.()->MotionSettings){settings=settings.copy(motion=settings.motion.f());save()};private fun editIsland(f:IslandSettings.()->IslandSettings){settings=settings.copy(island=settings.island.f());save()};private fun editQuick(f:QuickSpaceSettings.()->QuickSpaceSettings){settings=settings.copy(quickSpace=settings.quickSpace.f());save()};private fun editControl(f:ControlCenterSettings.()->ControlCenterSettings){settings=settings.copy(controlCenter=settings.controlCenter.f());save()};private fun editFloat(f:FloatingWindowSettings.()->FloatingWindowSettings){settings=settings.copy(floatingWindows=settings.floatingWindows.f());save()};private fun editSplit(f:SplitScreenSettings.()->SplitScreenSettings){settings=settings.copy(splitScreen=settings.splitScreen.f());save()};private fun editSecurity(f:SecuritySettings.()->SecuritySettings){settings=settings.copy(security=settings.security.f());save()}
    private fun text(s:String,size:Float,color:Int,bold:Boolean)=TextView(context).apply{text=s;textSize=size;setTextColor(color);if(bold)typeface=Typeface.DEFAULT_BOLD}
    private fun dp(v:Int)=(v*resources.displayMetrics.density).roundToInt()
}
